ST.xhtml:
standstill := (shutterValue = DomeShutterMotionStates.STANDSTILL) AND superState;
opening := (shutterValue = DomeShutterMotionStates.OPENING) AND superState;
closing := (shutterValue = DomeShutterMotionStates.CLOSING) AND superState;
stopping := (shutterValue = DomeShutterMotionStates.STOPPING) AND superState;
timeoutError := (shutterValue = DomeShutterMotionStates.TIMEOUT_ERROR) AND superState;
retryOpening := (shutterValue = DomeShutterMotionStates.RETRY_OPENING) AND superState;
retryClosing := (shutterValue = DomeShutterMotionStates.RETRY_CLOSING) AND superState;
unknownDriveLogicError := (shutterValue = DomeShutterMotionStates.UNKNOWN_DRIVE_LOGIC_ERROR) AND superState;

parts.shutter(
    initializationStatus := statuses.initializationStatus,
    operatorStatus := operatorStatus,
    operatingStatus := statuses.operatingStatus,
    activityStatus := activityStatus,
    config := config.shutter);
parts.rotation(
    initializationStatus := statuses.initializationStatus,
    operatorStatus := operatorStatus,
    operatingStatus := statuses.operatingStatus,
    config := config.rotation);
statuses.initializationStatus();
statuses.healthStatus(
    isGood := parts.shutter.statuses.healthStatus.isGood AND parts.rotation.statuses.healthStatus.isGood,
    hasWarning := parts.shutter.statuses.healthStatus.hasWarning OR parts.rotation.statuses.healthStatus.hasWarning);
statuses.busyStatus( isBusy := parts.shutter.statuses.busyStatus.busy OR parts.rotation.statuses.busyStatus.busy );
statuses.operatingStatus( superState := statuses.initializationStatus.initialized );
statuses.poweredStatus( isEnabled := parts.rotation.statuses.poweredStatus.enabled );
processes.initialize( isEnabled := (NOT(statuses.initializationStatus.locked)) AND (statuses.initializationStatus.shutdown OR (statuses.initializationStatus.initializingFailed OR statuses.initializationStatus.initialized)) );
processes.changeOperatingState( isEnabled := FALSE );
processes.lock( isEnabled := operatorStatus.tech );
processes.unlock( isEnabled := operatorStatus.tech AND statuses.initializationStatus.locked );
processes.reset( isEnabled := statuses.busyStatus.idle AND statuses.initializationStatus.initialized );
processes.powerOn( isEnabled := (NOT(statuses.initializationStatus.locked)) AND (statuses.initializationStatus.initialized AND processes.powerOn.statuses.busyStatus.idle) );
processes.powerOff( isEnabled := statuses.initializationStatus.initialized AND processes.powerOff.statuses.busyStatus.idle );
processes.syncWithAxes( isEnabled := statuses.initializationStatus.initialized AND (statuses.busyStatus.idle AND statuses.poweredStatus.enabled) );
processes.startTracking( isEnabled := statuses.poweredStatus.enabled AND (NOT(isTracking)) );
processes.stopTracking( isEnabled := isTracking );
processes.stop( isEnabled := statuses.busyStatus.busy OR (isTracking OR operatorStatus.tech) );
processes.moveKnownPosition( isEnabled := statuses.initializationStatus.initialized AND (statuses.busyStatus.idle AND statuses.poweredStatus.enabled) );

THIS^.parts.shutter._log(
    name := 'shutter',
    buffer := subBuffer);
THIS^.parts.rotation._log(
    name := 'rotation',
    buffer := subBuffer);
THIS^.processes.initialize._log(
    name := 'processes.initialize',
    buffer := subBuffer);
THIS^.processes.changeOperatingState._log(
    name := 'processes.changeOperatingState',
    buffer := subBuffer);
THIS^.processes.lock._log(
    name := 'processes.lock',
    buffer := subBuffer);
THIS^.processes.unlock._log(
    name := 'processes.unlock',
    buffer := subBuffer);
THIS^.processes.reset._log(
    name := 'processes.reset',
    buffer := subBuffer);
THIS^.processes.powerOn._log(
    name := 'processes.powerOn',
    buffer := subBuffer);
THIS^.processes.powerOff._log(
    name := 'processes.powerOff',
    buffer := subBuffer);
THIS^.processes.syncWithAxes._log(
    name := 'processes.syncWithAxes',
    buffer := subBuffer);
THIS^.processes.startTracking._log(
    name := 'processes.startTracking',
    buffer := subBuffer);
THIS^.processes.stopTracking._log(
    name := 'processes.stopTracking',
    buffer := subBuffer);
THIS^.processes.stop._log(
    name := 'processes.stop',
    buffer := subBuffer);
THIS^.processes.moveKnownPosition._log(
    name := 'processes.moveKnownPosition',
    buffer := subBuffer);
LOGGER(
    name := name,
    actualStatus := THIS^.actualStatus,
    previousStatus := THIS^.previousStatus,
    buffer := buffer,
    subBuffer := subBuffer,
    pHealthStatus := ADR(THIS^.statuses.healthStatus),
    pBusyStatus := ADR(THIS^.statuses.busyStatus));

statuses.apertureStatus(
    superState := NOT((dataRead.apertureState = DomeShutterApertureStates.UNKNOWN) OR (dataRead.apertureState = DomeShutterApertureStates.INVALID)),
    isOpen := dataRead.apertureState = DomeShutterApertureStates.FULLY_OPEN,
    isClosed := dataRead.apertureState = DomeShutterApertureStates.FULLY_CLOSED);
statuses.motionStatus( shutterValue := dataRead.motionState );
statuses.healthStatus(
    isGood := isConnected AND (processes.open.statuses.healthStatus.isGood AND (processes.close.statuses.healthStatus.isGood AND processes.stop.statuses.healthStatus.isGood)),
    hasWarning := (processes.open.statuses.healthStatus.hasWarning OR (processes.close.statuses.healthStatus.hasWarning OR processes.stop.statuses.healthStatus.hasWarning)) OR (statuses.busyStatus.idle AND statuses.apertureStatus.partiallyOpen));
statuses.busyStatus( isBusy := processes.open.statuses.busyStatus.busy OR (processes.close.statuses.busyStatus.busy OR processes.stop.statuses.busyStatus.busy) );
processes.open( isEnabled := statuses.healthStatus.isGood AND ((NOT(initializationStatus.locked)) AND (operatorStatus.tech OR (statuses.busyStatus.idle AND (initializationStatus.initialized AND (activityStatus.awake OR activityStatus.moving))))) );
processes.close( isEnabled := operatorStatus.tech OR (statuses.healthStatus.isGood AND ((NOT(initializationStatus.locked)) AND (statuses.busyStatus.idle AND initializationStatus.initialized))) );
processes.stop( isEnabled := statuses.busyStatus.busy );

parts.motorAxis( isEnabled := (NOT(initializationStatus.locked)) AND operatorStatus.tech );
parts.encoderAxis( isEnabled := (NOT(initializationStatus.locked)) AND operatorStatus.tech );
statuses.healthStatus(
    isGood := parts.motorAxis.statuses.healthStatus.isGood AND (parts.encoderAxis.statuses.healthStatus.isGood AND (processes.reset.statuses.healthStatus.isGood AND processes.stop.statuses.healthStatus.isGood)),
    hasWarning := parts.motorAxis.statuses.healthStatus.hasWarning OR (parts.encoderAxis.statuses.healthStatus.hasWarning OR (processes.reset.statuses.healthStatus.hasWarning OR processes.stop.statuses.healthStatus.hasWarning)));
statuses.busyStatus( isBusy := parts.motorAxis.statuses.busyStatus.busy OR (parts.encoderAxis.statuses.busyStatus.busy OR (processes.reset.statuses.busyStatus.busy OR processes.stop.statuses.busyStatus.busy)) );
statuses.poweredStatus( isEnabled := parts.motorAxis.statuses.poweredStatus.enabled );
processes.reset( isEnabled := statuses.busyStatus.idle );
processes.stop( isEnabled := statuses.busyStatus.busy OR operatorStatus.tech );
processes.moveAbsolute( isEnabled := statuses.busyStatus.idle AND statuses.poweredStatus.enabled );
processes.moveRelative( isEnabled := processes.moveAbsolute.isEnabled );
processes.powerOn( isEnabled := (NOT(initializationStatus.locked)) AND statuses.busyStatus.idle );
processes.powerOff( isEnabled := statuses.busyStatus.idle );

IF do_request THEN
    do_request_result := request( name := set.name );
    do_request := FALSE;
END_IF;
SUPER^();

THIS^.get.name := name;
THIS^.statuses.busyStatus( isBusy := TRUE );
THIS^.statuses.healthStatus( isGood := TRUE );

IF THIS^.statuses.enabledStatus.enabled THEN
    request := RequestResults.ACCEPTED;
    THIS^.start( name := name );
ELSE
    request := RequestResults.REJECTED;
END_IF;

IF do_request THEN
    do_request_result := request( position := set.position );
    do_request := FALSE;
END_IF;
SUPER^();

THIS^.get.position := position;
THIS^.statuses.busyStatus( isBusy := TRUE );
THIS^.statuses.healthStatus( isGood := TRUE );

IF THIS^.statuses.enabledStatus.enabled THEN
    request := RequestResults.ACCEPTED;
    THIS^.start( position := position );
ELSE
    request := RequestResults.REJECTED;
END_IF;
